  ((SELECT id FROM word_book WHERE code='CET4'), 'substitute',    '/ˈsʌbstɪtjuːt/',  'v.',  '代替',           'to put in place of',    'You can substitute milk for cream.',      '你可以用牛奶代替奶油。',       3, 18),
