  ((SELECT id FROM word_book WHERE code='CET4'), 'utilize',       '/ˈjuːtɪlaɪz/',    'v.',  '利用',           'to make use of',        'Utilize every resource.',                 '利用一切资源。',               3, 20),
  ((SELECT id FROM word_book WHERE code='CET4'), 'vague',         '/veɪɡ/',          'adj.','模糊的',         'unclear',               'His answer was vague.',                   '他的回答很模糊。',             3, 21),
  ((SELECT id FROM word_book WHERE code='CET4'), 'welfare',       '/ˈwelfeə(r)/',    'n.',  '福利',           'well-being',            'The welfare system is strong.',           '福利体系很完善。',             3, 22),
  ((SELECT id FROM word_book WHERE code='CET4'), 'yield',         '/jiːld/',         'v.',  '产生;让步',     'to produce or give up', 'The land yields crops.',                  '这片土地能产出庄稼。',         3, 23),
  ((SELECT id FROM word_book WHERE code='CET4'), 'innovative',    '/ˈɪnəveɪtɪv/',    'adj.','创新的',         'introducing new ideas', 'They proposed an innovative idea.',       '他们提出了创新的想法。',       3, 24),
  ((SELECT id FROM word_book WHERE code='CET4'), 'sustainable',   '/səˈsteɪnəbl/',   'adj.','可持续的',       'able to continue',      'Sustainable energy matters.',             '可持续能源很重要。',           3, 25);
INSERT INTO `word` (book_id, word, phonetic, part_of_speech, meaning_zh, meaning_en, example_en, example_zh, difficulty, sort_order) VALUES
  ((SELECT id FROM word_book WHERE code='CET6'), 'ambiguous',    '/æmˈbɪɡjuəs/',   'adj.','模棱两可的',     'unclear in meaning',    'His statement was ambiguous.',            '他的陈述模棱两可。',           4, 1),
  ((SELECT id FROM word_book WHERE code='CET6'), 'benevolent',   '/bəˈnevələnt/',  'adj.','仁慈的',         'kind and generous',     'A benevolent leader is rare.',            '仁慈的领导者很罕见。',         4, 2),
