  ((SELECT id FROM word_book WHERE code='CET6'), 'discrepancy',  '/dɪˈskrepənsi/', 'n.',  '差异',           'a difference',          'There is a discrepancy in the data.',     '数据中存在差异。',             4, 4),
  ((SELECT id FROM word_book WHERE code='CET6'), 'eloquent',     '/ˈeləkwənt/',    'adj.','雄辩的',         'fluent in speech',      'She gave an eloquent speech.',            '她发表了雄辩的演讲。',         4, 5),
  ((SELECT id FROM word_book WHERE code='CET6'), 'fluctuate',    '/ˈflʌktʃueɪt/',  'v.',  '波动',           'to vary irregularly',   'Prices fluctuate daily.',                 '价格每日波动。',               4, 6),
  ((SELECT id FROM word_book WHERE code='CET6'), 'gratitude',    '/ˈɡrætɪtjuːd/',  'n.',  '感激',           'thankfulness',          'I owe you my gratitude.',                 '我对你深表感谢。',             4, 7),
  ((SELECT id FROM word_book WHERE code='CET6'), 'hypothesis',   '/haɪˈpɒθəsɪs/',  'n.',  '假设',           'a proposed explanation','Test the hypothesis carefully.',          '仔细检验假设。',               4, 8),
  ((SELECT id FROM word_book WHERE code='CET6'), 'inherent',     '/ɪnˈhɪərənt/',   'adj.','固有的',         'existing as natural',   'It is an inherent risk.',                 '这是一种固有风险。',           4, 9),
  ((SELECT id FROM word_book WHERE code='CET6'), 'jeopardize',   '/ˈdʒepədaɪz/',   'v.',  '危及',           'to put at risk',        'Don''t jeopardize the project.',          '不要危及项目。',               4, 10),
  ((SELECT id FROM word_book WHERE code='CET6'), 'lavish',       '/ˈlævɪʃ/',       'adj.','奢华的',         'extravagant',           'They held a lavish party.',               '他们举办了奢华派对。',         4, 11),
  ((SELECT id FROM word_book WHERE code='CET6'), 'meticulous',   '/məˈtɪkjələs/',  'adj.','一丝不苟的',     'very precise',          'He is meticulous about details.',         '他对细节一丝不苟。',           4, 12),
  ((SELECT id FROM word_book WHERE code='CET6'), 'notorious',    '/nəʊˈtɔːriəs/',  'adj.','臭名昭著的',     'famous for bad reason', 'He is notorious for lying.',              '他因撒谎臭名昭著。',           4, 13),
  ((SELECT id FROM word_book WHERE code='CET6'), 'oblivious',    '/əˈblɪviəs/',    'adj.','未察觉的',       'unaware',               'She was oblivious to the noise.',         '她对噪音浑然不觉。',           4, 14),
  ((SELECT id FROM word_book WHERE code='CET6'), 'paradigm',     '/ˈpærədaɪm/',    'n.',  '范式',           'a model',               'It marks a paradigm shift.',              '这标志着范式转变。',           4, 15),
  ((SELECT id FROM word_book WHERE code='CET6'), 'quintessential','/ˌkwɪntɪˈsenʃl/','adj.','典型的',        'representing perfection','He is the quintessential hero.',         '他是典型的英雄。',             4, 16),
  ((SELECT id FROM word_book WHERE code='CET6'), 'resilient',    '/rɪˈzɪliənt/',   'adj.','有弹性的',       'able to recover',       'Children are resilient.',                 '孩子们恢复力很强。',           4, 17),
  ((SELECT id FROM word_book WHERE code='CET6'), 'scrutinize',   '/ˈskruːtənaɪz/', 'v.',  '仔细检查',       'to examine closely',    'The teacher scrutinized the essay.',      '老师仔细检查了论文。',         4, 18),
  ((SELECT id FROM word_book WHERE code='CET6'), 'transcend',    '/trænˈsend/',    'v.',  '超越',           'to go beyond',          'Art transcends language.',                '艺术超越语言。',               4, 19),
  ((SELECT id FROM word_book WHERE code='CET6'), 'unprecedented','/ʌnˈpresɪdentɪd/','adj.','空前的',        'never done before',     'This is an unprecedented event.',         '这是史无前例的事件。',         4, 20),
  ((SELECT id FROM word_book WHERE code='CET6'), 'vulnerable',   '/ˈvʌlnərəbl/',   'adj.','易受伤害的',     'open to attack',        'Children are vulnerable to scams.',       '孩子容易遭受骗局。',           4, 21),
  ((SELECT id FROM word_book WHERE code='CET6'), 'wholesome',    '/ˈhəʊlsəm/',     'adj.','有益健康的',     'good for well-being',   'A wholesome meal is essential.',          '健康的一餐很必要。',           4, 22),
  ((SELECT id FROM word_book WHERE code='CET6'), 'xenophobia',   '/ˌzenəˈfəʊbiə/', 'n.',  '排外',           'fear of foreigners',    'Xenophobia harms society.',               '排外伤害社会。',               5, 23),
  ((SELECT id FROM word_book WHERE code='CET6'), 'profound',     '/prəˈfaʊnd/',    'adj.','深远的',         'very great or intense', 'The book has profound meaning.',          '这本书寓意深远。',             4, 24),
  ((SELECT id FROM word_book WHERE code='CET6'), 'rigorous',     '/ˈrɪɡərəs/',     'adj.','严格的',         'extremely thorough',    'Rigorous testing is required.',           '需要严格的测试。',             4, 25);
INSERT INTO `word` (book_id, word, phonetic, part_of_speech, meaning_zh, meaning_en, example_en, example_zh, difficulty, sort_order) VALUES
  ((SELECT id FROM word_book WHERE code='POSTGRAD'), 'advocate',     '/ˈædvəkeɪt/',     'v.',  '提倡',           'to support publicly',   'They advocate climate action.',           '他们主张气候行动。',           4, 1),
  ((SELECT id FROM word_book WHERE code='POSTGRAD'), 'bias',         '/ˈbaɪəs/',        'n.',  '偏见',           'unfair preference',     'We must avoid bias.',                     '我们要避免偏见。',             4, 2),
  ((SELECT id FROM word_book WHERE code='POSTGRAD'), 'coherent',     '/kəʊˈhɪərənt/',   'adj.','连贯的',         'logically connected',   'Write a coherent essay.',                 '写一篇连贯的文章。',           4, 3),
  ((SELECT id FROM word_book WHERE code='POSTGRAD'), 'derive',       '/dɪˈraɪv/',       'v.',  '源自',           'to obtain from',        'The word derives from Latin.',            '这个词源自拉丁语。',           4, 4),
  ((SELECT id FROM word_book WHERE code='POSTGRAD'), 'empirical',    '/ɪmˈpɪrɪkl/',     'adj.','经验主义的',     'based on observation',  'Empirical evidence is required.',         '需要经验证据。',               4, 5),
  ((SELECT id FROM word_book WHERE code='POSTGRAD'), 'feasible',     '/ˈfiːzəbl/',      'adj.','可行的',         'achievable',            'Is the plan feasible?',                   '这个计划可行吗?',             4, 6),
  ((SELECT id FROM word_book WHERE code='POSTGRAD'), 'gauge',        '/ɡeɪdʒ/',         'v.',  '测量,评估',     'to estimate or measure','Hard to gauge his mood.',                 '很难揣测他的心情。',           4, 7),
  ((SELECT id FROM word_book WHERE code='POSTGRAD'), 'heterogeneous','/ˌhetərəˈdʒiːniəs/','adj.','异质的',       'diverse in content',    'The group is heterogeneous.',             '这个群体多样。',               4, 8),
  ((SELECT id FROM word_book WHERE code='POSTGRAD'), 'implication',  '/ˌɪmplɪˈkeɪʃn/',  'n.',  '含义,暗示',     'a possible meaning',    'Consider the implications.',              '考虑其含义。',                 4, 9),
  ((SELECT id FROM word_book WHERE code='POSTGRAD'), 'juxtapose',    '/ˌdʒʌkstəˈpəʊz/', 'v.',  '并列,并置',     'to place side by side', 'She juxtaposed the two ideas.',           '她并置了两个观点。',           4, 10),
  ((SELECT id FROM word_book WHERE code='POSTGRAD'), 'latent',       '/ˈleɪtnt/',       'adj.','潜在的',         'hidden, not visible',   'A latent talent emerged.',                '潜在的才能显现。',             4, 11),
  ((SELECT id FROM word_book WHERE code='POSTGRAD'), 'mitigate',     '/ˈmɪtɪɡeɪt/',     'v.',  '缓解',           'to make less severe',   'Steps to mitigate risk.',                 '减轻风险的措施。',             4, 12),
  ((SELECT id FROM word_book WHERE code='POSTGRAD'), 'nuance',       '/ˈnjuːɑːns/',     'n.',  '细微差别',       'subtle difference',     'Note every nuance.',                      '注意每一个细微差别。',         4, 13),
  ((SELECT id FROM word_book WHERE code='POSTGRAD'), 'overt',        '/əʊˈvɜːt/',       'adj.','明显的',         'open, not hidden',      'There was overt hostility.',              '有明显的敌意。',               4, 14),
  ((SELECT id FROM word_book WHERE code='POSTGRAD'), 'pervasive',    '/pəˈveɪsɪv/',     'adj.','遍布的',         'spreading widely',      'Social media is pervasive.',              '社交媒体无处不在。',           4, 15),
  ((SELECT id FROM word_book WHERE code='POSTGRAD'), 'reciprocate',  '/rɪˈsɪprəkeɪt/',  'v.',  '回报',           'to respond in kind',    'She reciprocated my smile.',              '她回以微笑。',                 4, 16),
  ((SELECT id FROM word_book WHERE code='POSTGRAD'), 'subsequent',   '/ˈsʌbsɪkwənt/',   'adj.','随后的',         'happening after',       'Subsequent events proved him right.',     '后续事件证明他是对的。',       4, 17),
  ((SELECT id FROM word_book WHERE code='POSTGRAD'), 'tenuous',      '/ˈtenjuəs/',      'adj.','脆弱的',         'thin or weak',          'Their bond is tenuous.',                  '他们的关系很脆弱。',           5, 18),
  ((SELECT id FROM word_book WHERE code='POSTGRAD'), 'ubiquitous',   '/juːˈbɪkwɪtəs/',  'adj.','无处不在的',     'present everywhere',    'Smartphones are ubiquitous.',             '智能手机无处不在。',           4, 19),
  ((SELECT id FROM word_book WHERE code='POSTGRAD'), 'validate',     '/ˈvælɪdeɪt/',     'v.',  '证实',           'to confirm',            'The results validate the theory.',        '结果证实了理论。',             4, 20),
  ((SELECT id FROM word_book WHERE code='POSTGRAD'), 'wane',         '/weɪn/',          'v.',  '衰退',           'to decrease',           'His influence began to wane.',            '他的影响开始减弱。',           4, 21),
  ((SELECT id FROM word_book WHERE code='POSTGRAD'), 'incentive',    '/ɪnˈsentɪv/',     'n.',  '激励',           'a motivating reward',   'Bonuses are an incentive.',               '奖金是一种激励。',             4, 22),
  ((SELECT id FROM word_book WHERE code='POSTGRAD'), 'paramount',    '/ˈpærəmaʊnt/',    'adj.','至关重要的',     'most important',        'Safety is paramount.',                    '安全至关重要。',               4, 23),
  ((SELECT id FROM word_book WHERE code='POSTGRAD'), 'reconcile',    '/ˈrekənsaɪl/',    'v.',  '调和',           'to make compatible',    'Hard to reconcile the two views.',        '调和这两种观点很难。',         4, 24),
  ((SELECT id FROM word_book WHERE code='POSTGRAD'), 'consensus',    '/kənˈsensəs/',    'n.',  '共识',           'general agreement',     'They reached a consensus.',               '他们达成了共识。',             4, 25);
INSERT INTO `word` (book_id, word, phonetic, part_of_speech, meaning_zh, meaning_en, example_en, example_zh, difficulty, sort_order) VALUES
  ((SELECT id FROM word_book WHERE code='IELTS'), 'adverse',       '/ˈædvɜːs/',       'adj.','不利的',         'unfavorable',           'Adverse weather delayed the flight.',     '恶劣天气导致航班延误。',       4, 1),
  ((SELECT id FROM word_book WHERE code='IELTS'), 'broaden',       '/ˈbrɔːdn/',       'v.',  '拓宽',           'to widen',              'Travel broadens the mind.',               '旅行开阔思想。',               3, 2),
  ((SELECT id FROM word_book WHERE code='IELTS'), 'commute',       '/kəˈmjuːt/',      'v.',  '通勤',           'to travel daily',       'I commute to work by bike.',              '我骑车上下班。',               3, 3),
  ((SELECT id FROM word_book WHERE code='IELTS'), 'demographic',   '/ˌdeməˈɡræfɪk/',  'adj.','人口统计的',     'related to population', 'Demographic trends matter.',              '人口趋势很重要。',             4, 4),
  ((SELECT id FROM word_book WHERE code='IELTS'), 'ecosystem',     '/ˈiːkəʊsɪstəm/',  'n.',  '生态系统',       'a biological community','Forests are vital ecosystems.',           '森林是重要的生态系统。',       4, 5),
  ((SELECT id FROM word_book WHERE code='IELTS'), 'forecast',      '/ˈfɔːkɑːst/',     'v.',  '预测',           'to predict',            'Experts forecast a recession.',           '专家预测经济衰退。',           3, 6),
  ((SELECT id FROM word_book WHERE code='IELTS'), 'globalization', '/ˌɡləʊbəlaɪˈzeɪʃn/','n.','全球化',        'worldwide integration', 'Globalization reshapes economies.',       '全球化重塑经济格局。',         4, 7),
  ((SELECT id FROM word_book WHERE code='IELTS'), 'habitat',       '/ˈhæbɪtæt/',      'n.',  '栖息地',         'natural environment',   'Polar bears'' habitat shrinks.',          '北极熊的栖息地正缩减。',       3, 8),
  ((SELECT id FROM word_book WHERE code='IELTS'), 'infrastructure','/ˈɪnfrəstrʌktʃə(r)/','n.','基础设施',     'basic facilities',      'Roads are key infrastructure.',           '道路是关键基础设施。',         4, 9),
  ((SELECT id FROM word_book WHERE code='IELTS'), 'jeopardy',      '/ˈdʒepədi/',      'n.',  '危险',           'danger of loss',        'Their job is in jeopardy.',               '他们的工作面临危险。',         4, 10),
  ((SELECT id FROM word_book WHERE code='IELTS'), 'literacy',      '/ˈlɪtərəsi/',     'n.',  '识字能力',       'ability to read',       'Improving literacy is essential.',        '提高识字率至关重要。',         3, 11),
  ((SELECT id FROM word_book WHERE code='IELTS'), 'mortality',     '/mɔːˈtæləti/',    'n.',  '死亡率',         'death rate',            'Child mortality has fallen.',             '儿童死亡率下降了。',           4, 12),
  ((SELECT id FROM word_book WHERE code='IELTS'), 'norm',          '/nɔːm/',          'n.',  '规范',           'a standard',            'Working from home is the new norm.',      '居家办公成了新常态。',         3, 13),
  ((SELECT id FROM word_book WHERE code='IELTS'), 'outcome',       '/ˈaʊtkʌm/',       'n.',  '结果',           'a result',              'The outcome was unexpected.',             '结果出乎意料。',               3, 14),
  ((SELECT id FROM word_book WHERE code='IELTS'), 'pollution',     '/pəˈluːʃn/',      'n.',  '污染',           'contamination',         'Air pollution affects health.',           '空气污染影响健康。',           3, 15),
  ((SELECT id FROM word_book WHERE code='IELTS'), 'questionnaire', '/ˌkwestʃəˈneə(r)/','n.', '调查问卷',       'a set of survey questions','Please complete this questionnaire.',   '请填写这份问卷。',             3, 16),
  ((SELECT id FROM word_book WHERE code='IELTS'), 'reform',        '/rɪˈfɔːm/',       'n.',  '改革',           'an improvement change', 'Education reform is needed.',             '需要教育改革。',               3, 17),
  ((SELECT id FROM word_book WHERE code='IELTS'), 'sustain',       '/səˈsteɪn/',      'v.',  '维持',           'to keep going',         'We must sustain the economy.',            '我们必须维持经济。',           4, 18),
  ((SELECT id FROM word_book WHERE code='IELTS'), 'tackle',        '/ˈtækl/',         'v.',  '处理',           'to deal with',          'We must tackle climate change.',          '我们必须应对气候变化。',       3, 19),
  ((SELECT id FROM word_book WHERE code='IELTS'), 'undergo',       '/ˌʌndəˈɡəʊ/',     'v.',  '经历',           'to experience',         'The city is undergoing change.',          '这座城市正经历变化。',         3, 20),
  ((SELECT id FROM word_book WHERE code='IELTS'), 'vegetation',    '/ˌvedʒəˈteɪʃn/',  'n.',  '植被',           'plant life of an area', 'The vegetation is dense.',                '植被密集。',                   3, 21),
  ((SELECT id FROM word_book WHERE code='IELTS'), 'workforce',     '/ˈwɜːkfɔːs/',     'n.',  '劳动力',         'all workers',           'The workforce is aging.',                 '劳动力正在老龄化。',           3, 22),
  ((SELECT id FROM word_book WHERE code='IELTS'), 'flexible',      '/ˈfleksəbl/',     'adj.','灵活的',         'easy to change',        'We need a flexible schedule.',            '我们需要灵活的日程。',         3, 23),
  ((SELECT id FROM word_book WHERE code='IELTS'), 'sufficient',    '/səˈfɪʃnt/',      'adj.','足够的',         'enough',                'We have sufficient resources.',           '我们有足够的资源。',           3, 24),
  ((SELECT id FROM word_book WHERE code='IELTS'), 'subsidy',       '/ˈsʌbsədi/',      'n.',  '补贴',           'financial assistance',  'Farmers receive a subsidy.',              '农民获得补贴。',               4, 25);
INSERT INTO `word` (book_id, word, phonetic, part_of_speech, meaning_zh, meaning_en, example_en, example_zh, difficulty, sort_order) VALUES
  ((SELECT id FROM word_book WHERE code='TOEFL'), 'abundant',      '/əˈbʌndənt/',     'adj.','丰富的',         'plentiful',             'The region has abundant rainfall.',       '该地区雨量丰富。',             4, 1),
  ((SELECT id FROM word_book WHERE code='TOEFL'), 'biodiversity',  '/ˌbaɪəʊdaɪˈvɜːsəti/','n.','生物多样性',    'variety of life',       'Biodiversity is declining.',              '生物多样性在下降。',           4, 2),
  ((SELECT id FROM word_book WHERE code='TOEFL'), 'civilization',  '/ˌsɪvəlaɪˈzeɪʃn/','n.',  '文明',           'an advanced society',   'Ancient civilizations fascinate us.',     '古代文明令人着迷。',           3, 3),
  ((SELECT id FROM word_book WHERE code='TOEFL'), 'displacement',  '/dɪsˈpleɪsmənt/', 'n.',  '取代,位移',     'movement from a place', 'War causes displacement.',                '战争造成流离失所。',           4, 4),
  ((SELECT id FROM word_book WHERE code='TOEFL'), 'emerge',        '/ɪˈmɜːdʒ/',       'v.',  '出现',           'to come into view',     'A new idea emerged.',                     '一个新想法出现了。',           3, 5),
  ((SELECT id FROM word_book WHERE code='TOEFL'), 'fossilize',     '/ˈfɒsəlaɪz/',     'v.',  '使...成化石',    'to preserve in rock',   'The bones fossilized over millennia.',    '骨骼经过千年成为化石。',       4, 6),
  ((SELECT id FROM word_book WHERE code='TOEFL'), 'gravity',       '/ˈɡrævəti/',      'n.',  '重力',           'attractive force',      'Gravity pulls objects down.',             '重力把物体拉向下方。',         3, 7),
  ((SELECT id FROM word_book WHERE code='TOEFL'), 'hypothesis',    '/haɪˈpɒθəsɪs/',   'n.',  '假说',           'an explanation guess',  'The hypothesis was tested.',              '假说得到验证。',               4, 8),
  ((SELECT id FROM word_book WHERE code='TOEFL'), 'indigenous',    '/ɪnˈdɪdʒənəs/',   'adj.','本土的',         'native to a region',    'These plants are indigenous.',            '这些植物是本土的。',           4, 9),
  ((SELECT id FROM word_book WHERE code='TOEFL'), 'jurisprudence', '/ˌdʒʊərɪsˈpruːdns/','n.','法理学',         'the science of law',    'Jurisprudence studies legal theory.',     '法理学研究法律理论。',         5, 10),
  ((SELECT id FROM word_book WHERE code='TOEFL'), 'kinetic',       '/kɪˈnetɪk/',      'adj.','动能的',         'related to motion',     'Kinetic energy is impressive.',           '动能令人印象深刻。',           4, 11),
  ((SELECT id FROM word_book WHERE code='TOEFL'), 'longevity',     '/lɒnˈdʒevəti/',   'n.',  '长寿',           'long life',             'Healthy diet supports longevity.',        '健康饮食有助长寿。',           4, 12),
  ((SELECT id FROM word_book WHERE code='TOEFL'), 'molecule',      '/ˈmɒlɪkjuːl/',    'n.',  '分子',           'tiny chemical unit',    'Water has H2O molecules.',                '水由 H2O 分子组成。',          3, 13),
